Abbreviation SEGS := Ubsan.M.loaded_segments.

Definition SMV      : Z := 0x66d94.
Definition MVA1E    : Z := 0x690e4.
Definition MVA1R    : Z := 0x66df8.
Definition MVA3E    : Z := 0x69254.
Definition X_PC     : Z := 0x66f30.
