  Definition SBall : list (Z * Z) := state_blocks c1 ++ state_blocks c2.

  Definition W : Z * Z := (sp - (64 + DEL_STACK), sp).
  Definition inblk (bs : list (Z * Z)) (a : Z) : Prop := exists b, In b bs /\ fst b <= a < fst b + snd b.

  Definition base_ok (R : bvmap 5 word) : Prop :=
    getr R 2%bv = Z_to_bv 64 (sp - 32) /\ getr R 3%bv = Z_to_bv 64 (ly_gp L) /\ getr R 4%bv = Z_to_bv 64 (ly_tp L)
    /\ getr R 8%bv = Z_to_bv 64 st1 /\ getr R 9%bv = Z_to_bv 64 st2
    /\ forall r, In r [19; 20; 21; 22; 23; 24; 25; 26; 27]%bv -> getr R r = getr R0 r.

  Definition frame (M : mem) : Prop :=
    cell8 SEGS M (sp - 8) ret /\ cell8 SEGS M (sp - 16) (bv_unsigned (getr R0 8%bv))
    /\ cell8 SEGS M (sp - 24) (bv_unsigned (getr R0 9%bv)) /\ cell8 SEGS M (sp - 32) (bv_unsigned (getr R0 18%bv)).

  Record gst (F : Z -> Prop) (bs : list (Z * Z)) (A : AS MI) (M : mem) (model : Model) (R : bvmap 5 word) : Prop := GST {
    g_ai : ainv MI A M model;
    g_ms : mstd model;
    g_fs : m_fs model = m_fs model0;
    g_fds : m_fds model = m_fds model0;
    g_regs : base_ok R;
    g_frame : frame M;
    g_def : defined M (sp - (64 + DEL_STACK)) (64 + DEL_STACK);
    g_win : forall a, zwin (sp - (64 + DEL_STACK)) sp a -> ~ owned MI A a;
    g_odef1 : defined M st1 240;
    g_odef2 : defined M st2 240;
    g_eff : eff MI A0 A M0 M W F;
    g_lap : lapply (live MI A0) (map (fun b => LDel (fst b)) bs) (live MI A);
    g_Fok : forall a, F a -> (st1 <= a < st1 + 240) \/ (st2 <= a < st2 + 240) \/ inblk SBall a;
    g_sub : forall b, In b bs -> In b (state_blocks c1)
  }.

  Lemma sp_facts : sp mod 16 = 0 /\ alloc_ceiling + (64 + DEL_STACK) <= sp /\ sp < 2 ^ 47 /\ 0x124000 <= sp - (64 + DEL_STACK).
