  #[local] Notation e11 := (t3c (st_m1 c1)).  #[local] Notation bl11 := (t3a (st_m1 c1)).  #[local] Notation bc11 := (t3b (st_m1 c1)).
  #[local] Notation e12 := (t3c (st_m2 c1)).  #[local] Notation bl12 := (t3a (st_m2 c1)).  #[local] Notation bc12 := (t3b (st_m2 c1)).
  #[local] Notation e13 := (t3c (st_m3 c1)).  #[local] Notation bl13 := (t3a (st_m3 c1)).  #[local] Notation bc13 := (t3b (st_m3 c1)).
  #[local] Notation e21 := (t3c (st_m1 c2)).  #[local] Notation bl21 := (t3a (st_m1 c2)).  #[local] Notation bc21 := (t3b (st_m1 c2)).
  #[local] Notation e22 := (t3c (st_m2 c2)).  #[local] Notation bl22 := (t3a (st_m2 c2)).  #[local] Notation bc22 := (t3b (st_m2 c2)).
  #[local] Notation e23 := (t3c (st_m3 c2)).  #[local] Notation bl23 := (t3a (st_m3 c2)).  #[local] Notation bc23 := (t3b (st_m3 c2)).

  Definition FP (a : Z) : Prop := (st1 <= a < st1 + 48) \/ umap_foot 24 (st1 + 48) bl11 bc11 e11 a \/ umap_foot 24 (st2 + 48) bl21 bc21 e21 a.
  Definition DP : list (Z * Z) := nblocks 24 e11 ++ ablock bl11 bc11.

  Ltac zpc z := lazymatch goal with |- srealizes _ (mkCfg (mkst _ ?pc _ _) _) _ =>
                  replace pc with (Z_to_bv 64 z : word) by (apply bv_eq; vm_compute; reflexivity) end.

  Lemma stageP :
    (forall (fx1 : FPState) A1 M1 model1 R1,
        @fp_csr fx1 = @fp_csr fx -> gst FP DP A1 M1 model1 R1 ->
        cell8 SEGS M1 st1 (st_words c2) -> cell8 SEGS M1 (st1 + 8) (st_nwords c2) -> cell8 SEGS M1 (st1 + 16) (st_diag c2) ->
        cell8 SEGS M1 (st1 + 24) (st_widx c2) -> cell8 SEGS M1 (st1 + 32) (st_icount c2) ->
        cell4 SEGS M1 (st1 + 40) (st_endian c2) -> cellw SEGS M1 (st1 + 44) 2 (st_flags c2) ->
        umapx MI 24 (nval24 SEGS) A1 M1 (st1 + 48) bl21 bc21 e21 ->
        umapx MI 24 (nval24 SEGS) A1 M1 (st2 + 48) 0 0 [] ->
        srealizes SEGS (cfg fx1 R1 MVA1R M1 model1) K) ->
