  Definition scal7 (M : mem) : Prop :=
    cell8 SEGS M st1 (st_words c2) /\ cell8 SEGS M (st1 + 8) (st_nwords c2) /\ cell8 SEGS M (st1 + 16) (st_diag c2) /\
    cell8 SEGS M (st1 + 24) (st_widx c2) /\ cell8 SEGS M (st1 + 32) (st_icount c2) /\
    cell4 SEGS M (st1 + 40) (st_endian c2) /\ cellw SEGS M (st1 + 44) 2 (st_flags c2).
  Definition resP (A : AS MI) (M : mem) : Prop :=
    scal7 M /\ umapx MI 24 (nval24 SEGS) A M (st1 + 48) bl21 bc21 e21 /\ umapx MI 24 (nval24 SEGS) A M (st2 + 48) 0 0 [].
  Definition resN (A : AS MI) (M : mem) : Prop :=
    umapx MI 32 (nval32 SEGS) A M (st1 + 88) bl22 bc22 e22 /\ umapx MI 32 (nval32 SEGS) A M (st2 + 88) 0 0 [].
  Definition resX (A : AS MI) (M : mem) : Prop :=
