  Lemma umapx_keep : forall NS V nval (HNS : 24 <= NS)
      (nval_agree : forall M M' p v, nval M p v -> agree_on M M' (p + 20) (NS - 20) -> 0 < p -> p + NS <= 2 ^ 47 -> nval M' p v)
      (A A' : AS MI) M M' model obj bl bc (ents : list (Z * (Z * V))) (W' : Z * Z) (F' : Z -> Prop),
    umapx MI NS nval A M obj bl bc ents -> ainv MI A M model -> eff MI A A' M M' W' F' ->
    sp <= obj -> snd W' <= sp -> alloc_ceiling <= fst W' ->
