  Lemma stageN : forall (fx1 : FPState) A1 M1 model1 R1,
    @fp_csr fx1 = @fp_csr fx -> gst FP DP A1 M1 model1 R1 -> resP A1 M1 ->
    (forall (fx2 : FPState) A2 M2 model2 R2,
        @fp_csr fx2 = @fp_csr fx -> gst FN DN A2 M2 model2 R2 -> resP A2 M2 -> resN A2 M2 ->
        srealizes SEGS (cfg fx2 R2 X_PC M2 model2) K) ->
